import pathlib
FILES = {
    'settings.gradle': "pluginManagement {\\n    repositories {\\n        gradlePluginPortal()\\n        maven {\\n            name = 'MinecraftForge'\\n            url = 'https://maven.minecraftforge.net/'\\n        }\\n    }\\n}\\n\\nplugins {\\n    id 'org.gradle.toolchains.foojay-resolver-convention' version '0.7.0'\\n}\\n\\nrootProject.name = 'fpvdrone'\\n",
    'src/main/java/com/example/fpvdrone/client/audio/DroneMotorSoundInstance.java': 'package com.example.fpvdrone.client.audio;\\n\\nimport com.example.fpvdrone.entity.FpvDroneEntity;\\nimport com.example.fpvdrone.registry.ModSounds;\\nimport net.minecraft.client.resources.sounds.AbstractTickableSoundInstance;\\nimport net.minecraft.client.resources.sounds.SoundInstance;\\nimport net.minecraft.sounds.SoundSource;\\nimport net.minecraft.util.Mth;\\n\\npublic class DroneMotorSoundInstance extends AbstractTickableSoundInstance {\\n    private final FpvDroneEntity drone;\\n\\n    public DroneMotorSoundInstance(FpvDroneEntity drone) {\\n        super(ModSounds.DRONE_MOTOR_LOOP.get(), SoundSource.NEUTRAL, SoundInstance.createUnseededRandom());\\n        this.drone = drone;\\n        this.looping = true;\\n        this.delay = 0;\\n        this.volume = 0.65F;\\n        this.pitch = 0.6F;\\n        this.x = drone.getX();\\n        this.y = drone.getY();\\n        this.z = drone.getZ();\\n    }\\n\\n    @Override\\n    public void tick() {\\n        if (drone.isRemoved()) {\\n            this.stop();\\n            return;\\n        }\\n        this.x = drone.getX();\\n        this.y = drone.getY();\\n        this.z = drone.getZ();\\n        float throttle = drone.getThrottle();\\n        this.pitch = Mth.clamp(0.6F + throttle * 1.6F, 0.6F, 2.2F);\\n        this.volume = 0.35F + throttle * 0.65F;\\n    }\\n\\n    public void stopSound() {\\n        this.stop();\\n    }\\n}\\n',
    'src/main/java/com/example/fpvdrone/entity/FpvDroneEntity.java': 'package com.example.fpvdrone.entity;\\n\\nimport com.example.fpvdrone.capability.PlayerDroneProvider;\\nimport com.example.fpvdrone.item.FpvGogglesItem;\\nimport com.example.fpvdrone.network.PacketHandler;\\nimport com.example.fpvdrone.network.S2CDroneDestroyedPacket;\\nimport com.example.fpvdrone.network.S2CDroneTelemetryPacket;\\nimport com.example.fpvdrone.registry.ModSounds;\\nimport net.minecraft.nbt.CompoundTag;\\nimport net.minecraft.network.protocol.Packet;\\nimport net.minecraft.network.protocol.game.ClientGamePacketListener;\\nimport net.minecraft.network.syncher.EntityDataAccessor;\\nimport net.minecraft.network.syncher.EntityDataSerializers;\\nimport net.minecraft.network.syncher.SynchedEntityData;\\nimport net.minecraft.server.level.ServerLevel;\\nimport net.minecraft.server.level.ServerPlayer;\\nimport net.minecraft.server.level.TicketType;\\nimport net.minecraft.sounds.SoundSource;\\nimport net.minecraft.util.Mth;\\nimport net.minecraft.world.entity.Entity;\\nimport net.minecraft.world.entity.EntityType;\\nimport net.minecraft.world.entity.EquipmentSlot;\\nimport net.minecraft.world.entity.LivingEntity;\\nimport net.minecraft.world.entity.MoverType;\\nimport net.minecraft.world.item.ItemStack;\\nimport net.minecraft.world.level.ChunkPos;\\nimport net.minecraft.world.level.Level;\\nimport net.minecraft.world.phys.AABB;\\nimport net.minecraft.world.phys.Vec3;\\nimport net.minecraftforge.network.NetworkHooks;\\nimport org.jetbrains.annotations.Nullable;\\nimport org.joml.Quaternionf;\\nimport org.joml.Vector3f;\\nimport software.bernie.geckolib.animatable.GeoEntity;\\nimport software.bernie.geckolib.core.animatable.instance.AnimatableInstanceCache;\\nimport software.bernie.geckolib.core.animation.AnimatableManager;\\nimport software.bernie.geckolib.core.animation.AnimationController;\\nimport software.bernie.geckolib.core.animation.AnimationState;\\nimport software.bernie.geckolib.core.animation.RawAnimation;\\nimport software.bernie.geckolib.core.object.PlayState;\\nimport software.bernie.geckolib.util.GeckoLibUtil;\\n\\nimport java.util.Comparator;\\nimport java.util.List;\\nimport java.util.Optional;\\nimport java.util.UUID;\\n\\npublic class FpvDroneEntity extends Entity implements GeoEntity {\\n    private static final TicketType<ChunkPos> DRONE_TICKET =\\n            TicketType.create("fpv_drone", Comparator.comparingLong(ChunkPos::toLong), 40);\\n\\n    private static final EntityDataAccessor<Float> DATA_QX =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Float> DATA_QY =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Float> DATA_QZ =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Float> DATA_QW =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Float> DATA_THROTTLE =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Float> DATA_BATTERY =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.FLOAT);\\n    private static final EntityDataAccessor<Optional<UUID>> DATA_OWNER =\\n            SynchedEntityData.defineId(FpvDroneEntity.class, EntityDataSerializers.OPTIONAL_UUID);\\n\\n    private static final RawAnimation SPIN_PROPS =\\n            RawAnimation.begin().thenLoop("animation.fpv_drone.spin_props");\\n\\n    private static final float GRAVITY_PER_TICK = 0.055F;\\n    private static final float AIR_DRAG = 0.96F;\\n    private static final float MAX_THRUST_ACCEL = 0.145F;\\n    private static final float PITCH_RATE_RAD = 0.095F;\\n    private static final float ROLL_RATE_RAD = 0.115F;\\n    private static final float YAW_RATE_RAD = 0.085F;\\n    private static final float EXPLOSION_RADIUS = 3.5F;\\n\\n    private final AnimatableInstanceCache animCache = GeckoLibUtil.createInstanceCache(this);\\n\\n    private final Quaternionf prevOrientation = new Quaternionf();\\n    private final Quaternionf orientation = new Quaternionf();\\n\\n    private float inputPitch = 0.0F;\\n    private float inputRoll = 0.0F;\\n    private float inputYaw = 0.0F;\\n    private float inputThrottleDelta = 0.0F;\\n    private int inputTimeoutTicks = 0;\\n    private int flightTicks = 0;\\n    private boolean detonated = false;\\n\\n    @Nullable\\n    private ChunkPos lastTicketChunk = null;\\n\\n    public FpvDroneEntity(EntityType<?> type, Level level) {\\n        super(type, level);\\n        this.blocksBuilding = true;\\n    }\\n\\n    @Override\\n    protected void defineSynchedData() {\\n        this.entityData.define(DATA_QX, 0.0F);\\n        this.entityData.define(DATA_QY, 0.0F);\\n        this.entityData.define(DATA_QZ, 0.0F);\\n        this.entityData.define(DATA_QW, 1.0F);\\n        this.entityData.define(DATA_THROTTLE, 0.25F);\\n        this.entityData.define(DATA_BATTERY, 16.8F);\\n        this.entityData.define(DATA_OWNER, Optional.empty());\\n    }\\n\\n    public void setInitialYaw(float yawDeg) {\\n        Quaternionf q = new Quaternionf().rotateY((float) Math.toRadians(-yawDeg));\\n        setOrientation(q);\\n        this.prevOrientation.set(q);\\n        this.setYRot(yawDeg);\\n        this.yRotO = yawDeg;\\n    }\\n\\n    public void setOwnerUuid(@Nullable UUID uuid) {\\n        this.entityData.set(DATA_OWNER, Optional.ofNullable(uuid));\\n    }\\n\\n    @Nullable\\n    public UUID getOwnerUuid() {\\n        return this.entityData.get(DATA_OWNER).orElse(null);\\n    }\\n\\n    public float getThrottle() {\\n        return this.entityData.get(DATA_THROTTLE);\\n    }\\n\\n    public void setThrottle(float throttle) {\\n        this.entityData.set(DATA_THROTTLE, Mth.clamp(throttle, 0.0F, 1.0F));\\n    }\\n\\n    public float getBatteryVoltage() {\\n        return this.entityData.get(DATA_BATTERY);\\n    }\\n\\n    public int getFlightTicks() {\\n        return this.flightTicks;\\n    }\\n\\n    public Quaternionf getOrientation() {\\n        return new Quaternionf(\\n                this.entityData.get(DATA_QX),\\n                this.entityData.get(DATA_QY),\\n                this.entityData.get(DATA_QZ),\\n                this.entityData.get(DATA_QW)\\n        ).normalize();\\n    }\\n\\n    public Quaternionf getInterpolatedOrientation(float partialTick) {\\n        Quaternionf current = getOrientation();\\n        return new Quaternionf(prevOrientation).slerp(current, partialTick).normalize();\\n    }\\n\\n    private void setOrientation(Quaternionf q) {\\n        q.normalize();\\n        this.orientation.set(q);\\n        this.entityData.set(DATA_QX, q.x);\\n        this.entityData.set(DATA_QY, q.y);\\n        this.entityData.set(DATA_QZ, q.z);\\n        this.entityData.set(DATA_QW, q.w);\\n    }\\n\\n    public void applyPilotInput(float pitch, float roll, float yaw, float throttleDelta) {\\n        this.inputPitch = Mth.clamp(pitch, -1.0F, 1.0F);\\n        this.inputRoll = Mth.clamp(roll, -1.0F, 1.0F);\\n        this.inputYaw = Mth.clamp(yaw, -1.0F, 1.0F);\\n        this.inputThrottleDelta = Mth.clamp(throttleDelta, -1.0F, 1.0F);\\n        this.inputTimeoutTicks = 5;\\n    }\\n\\n    @Override\\n    public void tick() {\\n        super.tick();\\n        this.prevOrientation.set(getOrientation());\\n        this.flightTicks++;\\n\\n        if (level().isClientSide) {\\n            this.orientation.set(getOrientation());\\n            return;\\n        }\\n\\n        updateChunkTicket();\\n\\n        if (inputTimeoutTicks > 0) {\\n            inputTimeoutTicks--;\\n        } else {\\n            inputPitch = 0.0F;\\n            inputRoll = 0.0F;\\n            inputYaw = 0.0F;\\n            inputThrottleDelta = 0.0F;\\n        }\\n\\n        float throttle = getThrottle();\\n        throttle = Mth.clamp(throttle + inputThrottleDelta * 0.045F, 0.0F, 1.0F);\\n        setThrottle(throttle);\\n\\n        // Drain LiPo 4S voltage slowly under load\\n        float currentVolt = getBatteryVoltage();\\n        float drain = 0.0004F + throttle * 0.0008F;\\n        this.entityData.set(DATA_BATTERY, Math.max(12.8F, currentVolt - drain));\\n\\n        // True Acro-mode rotation in local drone axes (no auto-leveling, no gimbal lock)\\n        Quaternionf q = getOrientation();\\n        q.rotateY(-inputYaw * YAW_RATE_RAD);\\n        q.rotateX(inputPitch * PITCH_RATE_RAD);\\n        q.rotateZ(-inputRoll * ROLL_RATE_RAD);\\n        setOrientation(q);\\n\\n        // Thrust along drone\'s local UP vector (0, 1, 0) rotated by orientation\\n        Vector3f localUp = new Vector3f(0.0F, 1.0F, 0.0F).rotate(q);\\n        Vec3 vel = this.getDeltaMovement();\\n        double thrust = throttle * MAX_THRUST_ACCEL;\\n\\n        double vx = (vel.x + localUp.x * thrust) * AIR_DRAG;\\n        double vy = (vel.y + localUp.y * thrust - GRAVITY_PER_TICK) * AIR_DRAG;\\n        double vz = (vel.z + localUp.z * thrust) * AIR_DRAG;\\n\\n        Vec3 nextVel = new Vec3(vx, vy, vz);\\n        this.setDeltaMovement(nextVel);\\n\\n        double preMoveSpeedSqr = nextVel.lengthSqr();\\n        this.move(MoverType.SELF, nextVel);\\n\\n        // Impact detection against blocks or living entities\\n        if (!detonated && flightTicks > 5) {\\n            boolean blockHit = this.horizontalCollision || this.verticalCollision;\\n            boolean entityHit = checkEntityCollision();\\n            if ((blockHit && preMoveSpeedSqr > 0.008) || entityHit) {\\n                detonate();\\n                return;\\n            }\\n        }\\n\\n        // Sync telemetry to owner every 2 ticks\\n        if (flightTicks % 2 == 0 && level() instanceof ServerLevel serverLevel) {\\n            UUID ownerUuid = getOwnerUuid();\\n            if (ownerUuid != null) {\\n                ServerPlayer owner = serverLevel.getServer().getPlayerList().getPlayer(ownerUuid);\\n                if (owner != null) {\\n                    PacketHandler.sendToPlayer(\\n                            new S2CDroneTelemetryPacket(\\n                                    this.getId(),\\n                                    this.getUUID(),\\n                                    throttle,\\n                                    getBatteryVoltage(),\\n                                    flightTicks,\\n                                    false\\n                            ),\\n                            owner\\n                    );\\n                }\\n            }\\n        }\\n    }\\n\\n    private boolean checkEntityCollision() {\\n        AABB box = this.getBoundingBox().inflate(0.18D);\\n        List<LivingEntity> hits = this.level().getEntitiesOfClass(LivingEntity.class, box,\\n                e -> e.isAlive() && (flightTicks > 20 || !e.getUUID().equals(getOwnerUuid())));\\n        return !hits.isEmpty();\\n    }\\n\\n    public void detonate() {\\n        if (detonated || level().isClientSide) {\\n            return;\\n        }\\n        detonated = true;\\n\\n        double ix = this.getX();\\n        double iy = this.getY();\\n        double iz = this.getZ();\\n\\n        level().playSound(null, ix, iy, iz, ModSounds.DRONE_EXPLOSION.get(),\\n                SoundSource.HOSTILE, 2.2F, 1.0F);\\n        level().explode(this, ix, iy, iz, EXPLOSION_RADIUS, Level.ExplosionInteraction.TNT);\\n\\n        if (level() instanceof ServerLevel serverLevel) {\\n            UUID ownerUuid = getOwnerUuid();\\n            if (ownerUuid != null) {\\n                ServerPlayer owner = serverLevel.getServer().getPlayerList().getPlayer(ownerUuid);\\n                if (owner != null) {\\n                    PacketHandler.sendToPlayer(new S2CDroneDestroyedPacket(ix, iy, iz), owner);\\n                    owner.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(\\n                            cap -> cap.clearBinding()\\n                    );\\n                    ItemStack head = owner.getItemBySlot(EquipmentSlot.HEAD);\\n                    if (head.getItem() instanceof FpvGogglesItem) {\\n                        FpvGogglesItem.setBoundDroneUuid(head, null);\\n                    }\\n                }\\n            }\\n        }\\n\\n        releaseChunkTicket();\\n        this.discard();\\n    }\\n\\n    private void updateChunkTicket() {\\n        if (!(level() instanceof ServerLevel serverLevel)) {\\n            return;\\n        }\\n        ChunkPos current = new ChunkPos(this.blockPosition());\\n        if (!current.equals(lastTicketChunk)) {\\n            if (lastTicketChunk != null) {\\n                serverLevel.getChunkSource().removeRegionTicket(DRONE_TICKET, lastTicketChunk, 2, lastTicketChunk);\\n            }\\n            serverLevel.getChunkSource().addRegionTicket(DRONE_TICKET, current, 2, current);\\n            lastTicketChunk = current;\\n        }\\n    }\\n\\n    private void releaseChunkTicket() {\\n        if (lastTicketChunk != null && level() instanceof ServerLevel serverLevel) {\\n            serverLevel.getChunkSource().removeRegionTicket(DRONE_TICKET, lastTicketChunk, 2, lastTicketChunk);\\n            lastTicketChunk = null;\\n        }\\n    }\\n\\n    @Override\\n    public void remove(RemovalReason reason) {\\n        releaseChunkTicket();\\n        super.remove(reason);\\n    }\\n\\n    @Override\\n    protected void readAdditionalSaveData(CompoundTag tag) {\\n        if (tag.hasUUID("Owner")) {\\n            setOwnerUuid(tag.getUUID("Owner"));\\n        }\\n        setThrottle(tag.getFloat("Throttle"));\\n        this.entityData.set(DATA_BATTERY, tag.contains("Battery") ? tag.getFloat("Battery") : 16.8F);\\n        this.flightTicks = tag.getInt("FlightTicks");\\n        if (tag.contains("QX")) {\\n            setOrientation(new Quaternionf(\\n                    tag.getFloat("QX"),\\n                    tag.getFloat("QY"),\\n                    tag.getFloat("QZ"),\\n                    tag.getFloat("QW")\\n            ));\\n        }\\n    }\\n\\n    @Override\\n    protected void addAdditionalSaveData(CompoundTag tag) {\\n        UUID owner = getOwnerUuid();\\n        if (owner != null) {\\n            tag.putUUID("Owner", owner);\\n        }\\n        tag.putFloat("Throttle", getThrottle());\\n        tag.putFloat("Battery", getBatteryVoltage());\\n        tag.putInt("FlightTicks", flightTicks);\\n        Quaternionf q = getOrientation();\\n        tag.putFloat("QX", q.x);\\n        tag.putFloat("QY", q.y);\\n        tag.putFloat("QZ", q.z);\\n        tag.putFloat("QW", q.w);\\n    }\\n\\n    @Override\\n    public Packet<ClientGamePacketListener> getAddEntityPacket() {\\n        return NetworkHooks.getEntitySpawningPacket(this);\\n    }\\n\\n    @Override\\n    public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {\\n        controllers.add(new AnimationController<>(this, "prop_controller", 0, this::propPredicate)\\n                .setAnimationSpeedHandler(entity -> 0.5D + entity.getThrottle() * 4.5D));\\n    }\\n\\n    private PlayState propPredicate(AnimationState<FpvDroneEntity> state) {\\n        return state.setAndContinue(SPIN_PROPS);\\n    }\\n\\n    @Override\\n    public AnimatableInstanceCache getAnimatableInstanceCache() {\\n        return animCache;\\n    }\\n}\\n',
}
for k, v in FILES.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Wrote", len(FILES), "files")
